\label{def:q-r-linear}
 Let $\{x^k\}_{k} \subset \mathbb{R}^n$ be a sequence converging to $x^* \in \mathbb{R}^n$. It is said that:
\begin{enumerate}
 \item[$(a)$] $\{x^k\}_{k}$ converges $Q$-linearly to $x^*$ if there exists a constant $r \in   ]0, 1[$ such that for all sufficiently large $k$, we have
 \begin{equation} \label{eq:q-linear}
  \|x^{k+1} - x^*\| \leq r \|x^k - x^*\|.
 \end{equation}

 \item[$(b)$] $\{x^k\}_{k}$ converges $R$-linearly to $x^*$ if there exists a constant $r \in   ]0, 1[$ and a constant $C > 0$ such that for all sufficiently large $k$, we have
 \begin{equation}\label{eq:r-linear}
  \|x^k - x^*\| \leq C r^k.
 \end{equation}
\end{enumerate}
Clearly, $Q$-linear convergence implies $R$-linear convergence, but the converse is not 
true in general. 
\qed

\label{def:wquasar-convex}
A function $h: \mathbb{R}^n \to \mathbb{R}$ is said to be $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$ if for every $x \in \mathbb{R}^n$ and every $\lambda \in [0,1]$, we have
\begin{equation}\label{eq:quasar-wconvex}
 h(\lambda \overline{x} + (1-\lambda)x) \leq \gamma \lambda h(\overline{x}) + (1-\gamma \lambda) h(x) + \frac{\gamma\rho}{2} \lambda \left(1-\frac{ \lambda}{2 -\gamma}\right)\|x - \overline{x}\|^2,
 \end{equation}
where $\gamma \in ]0,1]$ and $\rho \geq 0$. 
\qed

\label{example:02}
 Let $\gamma = \tfrac{1}{2}$, $\rho = \tfrac{5}{2}$, and define the function $h : \mathbb{R} \to \mathbb{R}$ by
\begin{equation}\label{eq:example}
 h(x) =  x^6 - 2x^4 + \tfrac{11}{10}x^2 = x^2 \left( \left(x^2-1\right)^2 + \tfrac{1}{10}\right) \geq 0.
\end{equation}
Clearly, $h(x) \geq 0$ for all $x \in \mathbb{R}$, $h(0) = 0$, and $h(x) \to +\infty$ as $|x| \to \infty$, hence $\overline{x} = 0$ is a global minimizer of $h$ on $\mathbb{R}$.

Furthermore, $h$ is $\left(\tfrac{5}{2},\tfrac{1}{2}\right)$-weakly quasar-convex with respect to $\overline{x} = 0$. With $\overline{x}=0$ and $h(\overline{x})=0$, the condition 
\eqref{eq:quasar-wconvex} becomes, for all $x\in\mathbb{R}$ and 
$\lambda\in[0,1]$,
\begin{equation}\label{eq:wqc-to-prove}
    h\!\left((1-\lambda)x\right) 
    \leq \left(1-\tfrac{\lambda}{2}\right)h(x) 
    + \tfrac{5\lambda}{8}\!\left(1-\tfrac{2\lambda}{3}\right)x^2,
\end{equation}
where we used $\gamma=\tfrac{1}{2}$, $\rho=\tfrac{5}{2}$, 
$\tfrac{\gamma\rho}{2}=\tfrac{5}{8}$, and $\tfrac{\lambda}{2-\gamma}=\tfrac{2\lambda}{3}$. Define the gap function
\begin{equation*}
    \Delta(\lambda,x) 
    := \left(1-\tfrac{\lambda}{2}\right)h(x) 
    + \tfrac{5\lambda}{8}\!\left(1-\tfrac{2\lambda}{3}\right)x^2 
    - h\!\left((1-\lambda)x\right).
\end{equation*}
We must show $\Delta(\lambda,x)\geq 0$ for all 
$x\in\mathbb{R}$ and $\lambda\in[0,1]$. Indeed, substituting $h(x)=x^6-2x^4+\tfrac{11}{10}x^2$, we decompose
\begin{equation*}
 \Delta(\lambda,x) = A_6(\lambda) x^6 + A_4(\lambda) x^4 + A_2(\lambda) x^2,
\end{equation*}
where the coefficients for all $\lambda\in[0,1]$ are
\begin{align*}
    A_6(\lambda) &:= \left(1-\tfrac{\lambda}{2}\right) 
                  - (1-\lambda)^6 =-\lambda^6+6 \lambda^5-15 \lambda^4+20 \lambda^3-15 \lambda^2+\tfrac{11}{2}\lambda  \in\left[0,\tfrac{1}{2}+\tfrac{5}{12 \sqrt[5]{12}}\right], \\
    A_4(\lambda) &:= -2\left(1-\tfrac{\lambda}{2}\right) 
                  + 2(1-\lambda)^4 =2 \lambda^4-8 \lambda^3+12 \lambda^2-7 \lambda  \in\left[-\tfrac{11}{8},0\right], \\
    A_2(\lambda) &:= \tfrac{11}{10}\!\left(1-\tfrac{\lambda}{2}\right) + \tfrac{5\lambda}{8}\!\left(1-\tfrac{2\lambda}{3}\right)  - \tfrac{11}{10}(1-\lambda)^2= -\tfrac{91}{60}\lambda^2+\tfrac{91}{40}\lambda  \in\left[0,\tfrac{273}{320} \right].
\end{align*}


Since $x^2 \geq 0$, we can view $\Delta(\lambda,x)$ as a cubic polynomial in $u = x^2 \geq 0$,
\begin{equation*}
 \Delta(\lambda,x) = u \big( A_6(\lambda) u^2 + A_4 (\lambda) u + A_2(\lambda) \big).
\end{equation*}
To show $\Delta(\lambda,x) \geq 0$, it suffices to prove that the quadratic $Q(u) = A_6 (\lambda) u^2 + A_4 (\lambda) u + A_2(\lambda)$ is non-negative for all $u \geq 0$ and all $\lambda \in [0,1]$. Since $A_6 (\lambda) \ge 0$ and $A_4(\lambda) \leq 0$ for all $\lambda \in [0,1]$, consider the quadratic
\begin{equation*}
 Q(u) = A_6 (\lambda)u^2 + A_4 (\lambda)u + A_2(\lambda), ~ \forall  u \ge 0.
\end{equation*}

\noindent\textbf{Case $\lambda=0$.} Here $A_6 (\lambda) = A_4(\lambda) = A_2(\lambda) = 0$, so $Q\equiv 0$.

\noindent\textbf{Case $\lambda\in]0,1]$.} Then $A_6(\lambda) > 0$, so $Q$ is an upward-opening parabola with vertex at
\begin{equation*}
u^*=-\tfrac{A_4(\lambda)}{2A_6(\lambda)}\ge 0,
\end{equation*}
because $A_4\leq 0$. Thus the global minimum of $Q$ over $\mathbb{R}$ already occurs at $u^*\ge 0$, and
\begin{equation}\label{eq:claim1}
Q(u)\ge 0 \ \ \forall u\ge0 
\Longleftrightarrow 
\min_{\mathbb R} Q =Q(u^*)= A_2(\lambda)-\tfrac{A_4(\lambda)^2}{4A_6(\lambda)}\ge 0
\Longleftrightarrow 
A_4(\lambda)^2 \leq 4A_6(\lambda)A_2(\lambda). 
\end{equation}

Hence it suffices to prove $A_4(\lambda)^2 \leq 4A_6(\lambda)A_2(\lambda)$ for all $\lambda\in[0,1]$.

Direct expansion gives, for all $\lambda$, that
$A_6(\lambda)=\lambda B_6(\lambda)$, $A_4(\lambda) = \lambda B_4 (\lambda)$ and $A_2(\lambda) = \lambda B_2 (\lambda)$, where
\begin{align*}
 B_2 (\lambda) = \tfrac{91}{120}(3-2\lambda), ~ B_4 (\lambda)  = -7+12\lambda-8\lambda^2 + 2 \lambda^3, ~\text{and}~ B_6 (\lambda) = \tfrac{11}{2}-15\lambda + 20 \lambda^2 - 15 \lambda^3+6\lambda^4-\lambda^5.
\end{align*}
For $\lambda=0$, \eqref{eq:claim1} is trivial. For $\lambda>0$, \eqref{eq:claim1} is equivalent to
\begin{equation}\label{eq:claim2}
 B_4 (\lambda)^2 \leq 4B_6(\lambda) B_2 (\lambda), ~ \forall  \lambda\in [0,1]. 
\end{equation}
Expanding both sides, 

$$
\begin{aligned}
B_4(\lambda)^2 &= 4 \lambda^6 -32 \lambda^5 + 112 \lambda^4-220 \lambda^3 + 256 \lambda^2 - 168 \lambda+49, 
\\
4B_6 (\lambda) B_2 (\lambda) &= \tfrac{91}{15} \lambda^6 - \tfrac{91}{2} \lambda^5 + \tfrac{728}{5} \lambda^4- \tfrac{1547}{6} \lambda^3 + 273 \lambda^2 -\tfrac{2548}{15} \lambda + \tfrac{1001}{20}.
\end{aligned}
$$

Define

\begin{equation*}
P(\lambda):=60\big(4B_6(\lambda)B_2(\lambda)-B_4(\lambda)^2\big)=124\lambda^6-810\lambda^5+2016\lambda^4-2270\lambda^3+1020\lambda^2-112\lambda+63.
\end{equation*}
Since  \eqref{eq:claim2} is equivalent to $P(\lambda)\ge 0$, it remains to show that
\begin{equation}\label{eq:claim3}
 P(\lambda) \ge 0, ~ \forall  \lambda \in [0,1]. 
\end{equation}

Write $P$ in the Bernstein basis \cite{farouki2012bernstein} of degree $6$ on $[0,1]$,

\begin{equation*}
P(\lambda)=\sum_{k=0}^{6} b_k \binom{6}{k}\lambda^k(1-\lambda)^{6-k}.
\end{equation*}

The coefficients $b_k$ are obtained from the power-basis coefficients $a_i$ of $P$ via the standard conversion

\begin{equation*}
b_k=\sum_{i=0}^{k}\tfrac{\binom{k}{i}}{\binom{6}{i}} a_i, ~a_0=63,~ a_1=-112,~ a_2=1020,~ a_3=-2270,~ a_4=2016,~ a_5=-810,~ \text{and}~ a_6=124.
\end{equation*}

Carrying out this computation gives $b_0=63$,  $b_1 = \tfrac{133}{3}$, $b_2=\tfrac{281}{3}$, $b_3 = \tfrac{195}{2}$, $b_4=\tfrac{1151}{15}$, $b_5 = \tfrac{155}{3}$ and $b_6=31$. Since the Bernstein basis polynomials $\binom{6}{k}\lambda^k(1-\lambda)^{6 - k}$ are non-negative for $\lambda \in [0,1]$, we conclude
\begin{equation*}
 P(\lambda) = \sum_{k=0}^{6} b_k \binom{6}{k} \lambda^k (1-\lambda)^{6-k} \ge 0, ~ \forall  \lambda \in[0,1],
\end{equation*}
which establishes \eqref{eq:claim3}.


On the other hand, $h$ is not $\gamma$-quasar-convex at $\overline{x} = 0$ for any $\gamma \in  ]0,1]$. Indeed, if $h$ is $\gamma$-quasar-convex at $\overline{x}=0$ (with $h(\overline{x})=0$), then for all $x \in \mathbb{R}$ and all $\lambda \in [0,1]$, we should have $h \left((1-\lambda) x\right) \leq (1-\gamma \lambda) h(x)$. In particular, take $x = 1$ and $\lambda = \tfrac{1}{2}$. Then, $h(\tfrac{1}{2}) \leq \left( 1 - \tfrac{\gamma}{2} \right) h(1)$. Substituting $h(1) = \tfrac{32}{320}$ and $h(\tfrac{1}{2}) = \tfrac{53}{320}$, we get
 $$ \tfrac{53}{320} \leq \left(1-\tfrac{\gamma}{2} \right) \tfrac{32}{320} ~ \implies ~ 53 \leq 32 - 16 \gamma \implies \gamma \leq -\tfrac{21}{16},$$
 a contradiction. Therefore, $h$ is not quasar-convex for any $\gamma \in  ]0, 1]$.

\qed

\label{prop:wqcx-radial}
 Let $f: \mathbb{R} \to \mathbb{R}$ be a function with $0 \in \operatorname{argmin}_{\mathbb{R}} f$, $f(0)=0$, and let $g: \mathbb{R}^n \to \mathbb{R}$ be a function such that $1 \leq g \leq M$ for some constant $M > 0$. Define,

\begin{equation*}
     h(x) := \begin{cases}
        f(\|x\|) ~ g\left(\tfrac{x}{\|x\|}\right), &  x \in \mathbb{R}^n \setminus \{0\}\\
        0. & x=0
    \end{cases}
\end{equation*}

If $f$ is $(\rho, \gamma)$-weakly quasar-convex with respect to $0$, with $\rho\geq 0$ and $\gamma \in ]0,1]$, then $h$ is $(M \rho, \gamma)$-weakly quasar-convex with respect to $0$.

First, we verify that $0 \in \operatorname{argmin}_{\mathbb{R}^n} h$. Since $f(0)=0$ and $0 \in \operatorname{argmin}_{\mathbb{R}} f$, we have $f(t) \ge 0$ for all $t \ge 0$. Also, $g \ge 1 > 0$. Hence, for any $x \in \mathbb{R}^n$, we have
\begin{equation*}
h(x) = f(\|x\|) ~ g\left(\tfrac{x}{\|x\|}\right) \ge 0 = h(0),
\end{equation*}
with equality if and only if $f(\|x\|)=0$. Thus, $0 \in \operatorname{argmin}_{\mathbb{R}^n} h$.

\noindent
Now, fix $y \in \mathbb{R}^n$, $\lambda \in [0,1]$, and let $\overline{x} = 0$. Since $h(0)=0$ and $\overline{x}=0$,
\begin{equation*}
h(\lambda \overline{x} + (1-\lambda)y) = h((1-\lambda)y) = f((1-\lambda)\|y\|) ~ g\left(\tfrac{y}{\|y\|}\right).
\end{equation*}

Since $f$ is $(\rho, \gamma)$-weakly quasar-convex with respect to $0$, we have
\begin{equation*}
f((1-\lambda)\|y\|) \leq (1-\gamma\lambda) f(\|y\|) + \tfrac{\gamma\rho}{2}\lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right)\|y\|^2.
\end{equation*}

Multiplying by $g(y/\|y\|) \ge 0$ and using $g \ge 1$, we obtain
\begin{align*}
 h((1-\lambda)y) & = f((1-\lambda)\|y\|) ~ g \left( \tfrac{y}{\|y\|}\right) \\
 & \leq (1-\gamma\lambda) f(\|y\|) ~ g\left( \tfrac{y}{\|y\|}\right) + \tfrac{\gamma\rho}{2} \lambda \left( 1 - \tfrac{\lambda}{2-\gamma}\right)\|y\|^2 ~ g \left(\tfrac{y}{\|y\|}\right) \\
 & = (1-\gamma\lambda) h(y) + \tfrac{\gamma\rho}{2} \lambda \left(1 - \tfrac{\lambda}{2-\gamma} \right) \|y\|^2 ~ g\left(\tfrac{y}{\|y\|}\right).
\end{align*}

Since $1 \leq g(y/\|y\|) \leq M$, we have $g\left( \tfrac{y}{\|y\|} \right) \leq M$. Thus,
\begin{equation*}
 h((1-\lambda)y) \leq (1- \gamma \lambda) h(y) + \tfrac{ \gamma (M\rho)}{2} \lambda\left(1 - \tfrac{ \lambda}{2 - \gamma} \right)\|y\|^2.
\end{equation*}

This is exactly the $(M\rho, \gamma)$-weakly quasar-convex inequality for $h$ with respect to $0$. Therefore, $h$ is $(M\rho, \gamma)$-weakly quasar-convex with respect to $0$.

\label{exam:large} {\bf (Strictly Large)}
 Let $f: [-1,1] \to \mathbb{R}$ be the function given by
$$f(s) = 2-\sqrt{|s|},$$
and $g$ be the function of Example \ref{example:02}, i.e., $g(s) = s^2 \left((s^2-1)^2 + \tfrac{1}{ 10}\right) \geq 0$.

Clearly, $f$ is positive on $[-1,1]$, but $f$ is not weakly convex on $[-1,1]$ for any modulus, since the one-sided derivatives at $s=0$ are $\{\pm\infty\}$. Also, since $(s^2-1)^2+\tfrac{1}{10} \geq \tfrac{1}{10} > 0$ for all $s$, we have $g(s)=0$ if and only if $s=0$, so $0$ is the unique global minimizer of $g$ on $\mathbb{R}$. By Example \ref{example:02}, $g$ is $\left( \tfrac{5}{2}, \tfrac{1}{2} \right)$-weakly quasar-convex with respect to $0$, and $g$ is not $\gamma$-quasar-convex with respect to $0$ for any $\gamma \in ~ ]0,1]$.

Set
\begin{equation*}
 \mathcal{A} := \left\{(x_1,x_2)\in\mathbb{R}^2 ~ : ~ x_1 \geq 0,   -x_1 \leq x_2 \leq x_1 \right\},
\end{equation*}
and define the function $h : \mathcal{A}  \to \mathbb{R}$ by
\begin{equation}\label{the:function}
 h(x_1,x_2) :=
 \begin{cases}
    g(x_1) ~ f\left(\dfrac{x_2}{x_1} \right), & (x_1,x_2) \neq (0,0), \\
    0, & (x_1,x_2) = (0,0).
\end{cases}
\end{equation}

Since $g \geq 0$ and $f > 0$ on $[-1,1]$, we have $h \geq 0$ on $\mathcal{A}$. Moreover, for $(x_1,x_2)\in \mathcal{A}$ with $x_1 > 0$, $h(x_1,x_2) = g(x_1)f(x_2/x_1) > 0$ since $g(x_1)>0$ and $f>0$, and for $x_1=0$, the domain constraint of $\mathcal{A}$ forces $x_2=0$. Hence $\overline{x}=(0,0)$ is the unique global minimizer of $h$ on $\mathcal{A}$, i.e., $\{(0, 0)\} = \operatorname{argmin}_\mathcal{A}~h$. Moreover, along the ray $x_2=0$, $h(t,0) = f(0) g(t) = 2g(t) \to 0$ as $t \downarrow 0$, and more generally, since $f$ is bounded on $[-1, 1]$ and $g(x_1) \to g(0)=0$ as $x_1\downarrow 0$,
$$h(x_1,x_2) = g(x_1)~f\left(\frac{x_2}{x_1} \right) \to 0$$
uniformly over $x_2/x_1 \in [-1,1]$ as $x_1 \downarrow 0$, thus $h$ is continuous at the origin.

We claim that $h$ is weakly quasar-convex with respect to $(0,0)$, but is neither weakly convex nor quasi-convex nor quasar-convex on $\mathcal{A}$ for any modulus. Indeed, let us prove this point by point:

\medskip
\noindent
\emph{(i) $h$ is weakly quasar-convex with respect to $(0,0)$:} On any ray through the origin, the ratio $x_2/x_1$ is constant, say $x_2/x_1=c \in [-1,1]$, so restricted to that ray, $h(t,ct) = f(c)~g(t)$ is a positive scalar multiple of $g$, with $f(c) \in [1,2]$. Since $g$ is $\left(\tfrac{5}{2}, \tfrac{1}{2} \right)$-weakly quasar-convex with respect to $0$, multiplying  \eqref{eq:quasar-wconvex} (with $g(0)=0$) by the positive constant $f(c)$ preserves $\gamma = \tfrac{1}{2}$ while scaling $\rho$ by $f(c)$, yielding
\begin{equation*}
h\big((1-\lambda)x_1, (1-\lambda)x_2\big) \leq \left(1-\tfrac{\lambda}{2}\right)h(x_1,x_2) + \frac{\tfrac{1}{2} \cdot f(c) \cdot \tfrac{5}{2}}{2} \lambda\left(1-\tfrac{2\lambda}{3}\right) x_1^2.
\end{equation*}
Since $x = (x_1, c x_1)$, we have $\|x\|^2 = x_1^2(1+c^2) \geq x_1^2$. Using $x_1^2 \leq \|x\|^2$ together with $f(c) \leq 2$, we get $f(c) \cdot \tfrac{5}{2} \leq 5$, which gives
\begin{equation*}
h\big((1-\lambda)x\big) \leq \left(1-\tfrac{\lambda}{2}\right)h(x) + \frac{\tfrac{1}{2} \cdot 5}{2} \lambda\left(1-\tfrac{2\lambda}{3}\right) \|x\|^2.
\end{equation*}
Thus, $h$ is $\left(5, \tfrac{1}{2} \right)$-weakly quasar-convex with respect to $(0, 0)$ on $\mathcal{A}$.

\medskip
\noindent
\emph{(ii) $h$ is not weakly convex on $\mathcal{A}$ for any modulus:} Fix $\rho\geq 0$ and consider, for $s \in ~ ]0, 1]$, the points $(1, -s), (1, s) \in \mathcal{A}$ and their midpoint $\tfrac{1}{2} (1,-s) + \tfrac{1}{2} (1, s) = (1,0)$. Since $f$ is even, $h(1,-s) = h(1,s) = g(1) f(s)$, and $h(1,0) = g(1) f(0)$. Weak convexity with modulus $\rho$ would require
\begin{equation*}
 g (1)f(0) \leq g(1) f(s) + \tfrac{\rho}{2} \cdot \tfrac14(2s)^2 = g(1) f(s)+\tfrac{\rho}{2}s^2,
\end{equation*}
i.e., using $f(0)-f(s)=\sqrt{s}$, we get $g(1)\sqrt{s} \leq \tfrac{\rho}{2}s^2$.

Since $g(1) = 1-2+\tfrac{11}{10} = \tfrac{1}{10} > 0$, dividing by $\sqrt{s}>0$ gives $\tfrac1{10} \leq \tfrac{\rho}{2}s^{3/2}$, which fails as $s\downarrow 0$ for any fixed $\rho\geq 0$. Hence, $h$ is not $\rho$-weakly convex on $\mathcal{A}$ for any $\rho\geq 0$.

\medskip
\noindent
\emph{(iii) $h$ is not quasi-convex, not star quasi-convex, and not quasar-convex on $\mathcal{A}$ for any modulus:} It suffices to consider $h$ restricted to the half-line $(t,0)$, $t\geq 0$, where $h(t,0) = f(0) g (t) = 2g(t)$. Using $g(0)=0$, $g(1) = \tfrac{1}{10} = \tfrac{32}{320}$, and $g \left( \tfrac{1}{2} \right) = \tfrac{53}{320}$ (see Example \ref{example:02}), we get
\begin{equation*}
h(0,0)=0, \quad h(1,0) = \tfrac{1}{5} = \tfrac{32}{160}, \quad\text{and}\quad h\!\left(\tfrac12,0\right) = \tfrac{53}{160}.
\end{equation*}
Since $\tfrac{53}{160} > \tfrac{32}{160}$, the point $\left(\tfrac12,0\right)$, which lies on the segment joining $(0,0)$ and $(1,0)$, satisfies $h\left( \tfrac12, 0 \right) > \max\{h(0,0), h(1,0)\}$, which directly violates quasi-convexity and, in particular, star quasi-convexity with respect to $(0, 0)$ (see \cite[Theorem 12]{PQK-L}).

Furthermore, $h$ is not $\gamma$-quasar-convex with respect to $(0,0)$ for any $\gamma\in~]0,1]$. Indeed, taking $x=(1,0)$ and $\lambda=\tfrac12$ in the quasar-convexity inequality $h((1-\lambda)x)\leq(1-\gamma\lambda)h(x)$ reduces, after cancelling the common factor of $2$ from $h(t,0)=2g(t)$, to $g\!\left(\tfrac12\right)\leq\left(1-\tfrac{\gamma}{2}\right)g(1)$, i.e., $\tfrac{53}{320}\leq\left(1-\tfrac{\gamma}{2}\right)\tfrac{32}{320}$, which is exactly the inequality shown in Example~\ref{example:02} to force $\gamma\leq-\tfrac{21}{16}$, a contradiction.


Therefore, $h$ is weakly quasar-convex on $\mathcal{A}$ with respect to $(0,0)$ (indeed $\left(5,\tfrac12\right)$-weakly quasar-convex), yet neither weakly convex, nor quasi-convex, nor star quasi-convex, nor quasar-convex, for any modulus.
\qed

\label{prop:quasar-ray}
$h$ is $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$ (where $\rho \geq 0$, $\gamma \in   ]0, 1]$) if and only if for every $d \in \mathbb{R}^n$ with $\|d\|=1$, the function
\begin{equation}\label{eq:quasar-ray}
 \varphi_d(t) := h(\overline{x} + td), \quad t \geq 0,
\end{equation}
is $(\rho,\gamma)$-weakly quasar-convex with respect to $t = 0$ on $[0, +\infty[$, i.e., for every $t \geq 0$ and every $\lambda \in [0,1]$, we have
\begin{equation}
\varphi_d\bigl((1-\lambda)t\bigr) \leq \gamma\lambda  \varphi_d(0) + (1 - \gamma\lambda) \varphi_d(t) + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) t^2. \label{1d:char}
\end{equation}

\label{prop:weak-quasar-shift}
 Let $h: \mathbb{R}^n \to\mathbb{R}$ and let $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$. For $\gamma \in ]0,1]$ and $\rho \ge 0$, define
 \begin{equation}\label{eq:shifted-function}
  g(x) := h(x) + \tfrac{\gamma \rho}{2 (2-\gamma)} \|x - \overline{x}\|^2.
 \end{equation}
 Then $h$ is $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x}$ if and only if $g$ is $\gamma$-quasar-convex with respect to $\overline{x}$.

Clearly, $\overline{x} \in \operatorname{argmin}_{ \mathbb{R}^n} g$. Furthermore, throughout the proof, ``$g$ is $\gamma$-quasar-convex with respect to $\overline{x}$'' refers to the $\rho = 0$ instance of \eqref{eq:quasar-wconvex}, namely
\begin{equation}\label{eq:QC}
 g(\lambda \overline{x} + (1-\lambda)x) \leq \gamma \lambda g(\overline{x}) + (1-\gamma\lambda) g(x), ~ \forall  x \in \mathbb{R}^n, ~ \forall  \lambda \in [0,1].
\end{equation}

Set $c := \frac{\gamma\rho}{2(2-\gamma)}$. Since $\gamma \in ]0,1]$, we have $2-\gamma \ge 1 > 0$, so $c$ is well defined and $c \ge 0$ because $\rho \ge 0$. Furthermore, the term $c\|x-\overline{x}\|^{2}$ is non-negative for every $x \in \mathbb{R}^n$, vanishing precisely at $x = \overline{x}$ when $\rho > 0$ (and identically, with $g = h$, when $\rho = 0$). Consequently,
\begin{equation*}
 g(x) - g(\overline{x}) = \big(h(x) - h (\overline{x}) \big) + c\|x - \overline{x}\|^{2} \ge 0, ~ \forall  x \in \mathbb{R}^n,
\end{equation*}

since both summands are non-negative, the first because $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$. It therefore follows that $\overline{x}$ is likewise a global minimizer of $g$ over $\mathbb{R}^n$, thus the base point $\overline{x}$ remains valid for the shifted function $g$, and the assertion that $g$ is $\gamma$-quasar-convex with respect to $\overline{x}$ is consequently well posed.

Fix $x \in \mathbb{R}^n$ and $\lambda \in [0,1]$, and set $z_\lambda := \lambda \overline{x} + (1-\lambda)x$. Since $z_\lambda - \overline{x} = (1-\lambda)(x - \overline{x})$, we have $\|z_\lambda - \overline{x}\|^{2} = (1-\lambda)^{2}\|x-\overline{x}\|^{2}$, thus

\begin{equation*}
g(\overline{x}) = h(\overline{x}), \quad g(x) = h(x) + c\|x-\overline{x}\|^{2}, \quad\text{and}\quad g(z_\lambda) = h(z_\lambda) + c(1-\lambda)^{2}\|x-\overline{x}\|^{2}.
\end{equation*}

Substituting these three expressions in \eqref{eq:QC} and rearranging shows that $g(z_\lambda) \leq \gamma\lambda g(\overline{x}) + (1-\gamma\lambda) g(x)$ holds if and only if

\begin{equation*}
 h(z_\lambda) \leq \gamma\lambda h(\overline{x}) + (1-\gamma \lambda) h(x) + c \Big((1-\gamma\lambda) - (1-\lambda)^{2}\Big) \|x-\overline{x}\|^{2}.
\end{equation*}

A direct expansion gives $(1-\gamma\lambda) - (1-\lambda)^{2} = \lambda(2-\gamma-\lambda)$, so that

\begin{equation*}
 c \Big((1-\gamma\lambda) - (1-\lambda)^{2}\Big) = \tfrac{\gamma \rho}{2(2-\gamma)} \lambda(2-\gamma-\lambda) = \tfrac{\gamma \rho}{2}\lambda\left(1 - \tfrac{\lambda}{2-\gamma} \right),
\end{equation*}

which is exactly the coefficient of $\|x-\overline{x}\|^2$ appearing in \eqref{eq:quasar-wconvex}. Then, for every $x \in \mathbb{R}^n$ and every $\lambda \in [0,1]$, the inequality $g(z_\lambda) \leq \gamma\lambda g(\overline{x}) + (1-\gamma\lambda)g(x)$ holds if and only if

\begin{equation*}
h(z_\lambda) \leq \gamma\lambda h(\overline{x}) + (1-\gamma\lambda) h(x) + \tfrac{\gamma\rho}{2}\lambda\left(1-\tfrac{\lambda}{2-\gamma}\right)\|x-\overline{x}\|^{2},
\end{equation*}

that is, precisely when inequality \eqref{eq:quasar-wconvex} holds for $h$ at the same pair $(x, \lambda)$. Since both notions of quasar-convexity require their defining inequality to hold for every $x \in \mathbb{R}^n$ and every $\lambda \in [0,1]$, taking the conjunction over all such pairs on each side yields $h$ is $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x}$ if and only if $g$ is $\gamma$-quasar-convex with respect to $\overline{x}$, 
which proves the proposition.

Since $A$ is linear and $A\overline{x} = \overline{y}$, we have for every $x \in \mathbb{R}^n$ and every $\lambda \in [0,1]$ that $A \bigl(\lambda \overline{x} + (1-\lambda)x\bigr) = \lambda A\overline{x} + (1-\lambda)Ax = \lambda \overline{y} + (1-\lambda)Ax$. Applying the $(\rho, \gamma)$-weak quasar-convexity of $h$ at $\overline{y}$ with $y = Ax$ yields
\begin{align}
 g\bigl(\lambda \overline{x} + (1-\lambda)x\bigr) & = h\bigl(A(\lambda \overline{x} + (1-\lambda)x) \bigr) = h\bigl(\lambda \overline{y} + (1-\lambda) Ax\bigr) \notag \\
 & \leq \gamma\lambda  h(\overline{y}) + (1 - \gamma\lambda)  h(Ax) + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \|Ax - \overline{y}\|^2. \label{eq:quasar-op}
\end{align}
Since $\overline{y} = A\overline{x}$, we have $\|Ax - \overline{y}\| = \|A(x - \overline{x})\|$. By definition of the operator norm,
\begin{equation*}
\|A(x - \overline{x})\| \leq \|A\|_{\mathrm{op}}  \|x - \overline{x}\| ~ \Longrightarrow ~ \|Ax - \overline{y}\|^2 \leq \|A\|_{\mathrm{op}}^2  \|x - \overline{x}\|^2.
\end{equation*}
Substituting this into \eqref{eq:quasar-op} and using $g(\overline{x}) = h(\overline{y})$ and $g(x) = h(Ax)$, we obtain
\begin{align*}
g\bigl(\lambda \overline{x} + (1-\lambda)x\bigr) 
&\leq \gamma\lambda  g(\overline{x}) + (1 - \gamma\lambda)  g(x) + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \|A\|_{\mathrm{op}}^2  \|x - \overline{x}\|^2 \\
&= \gamma\lambda  g(\overline{x}) + (1 - \gamma\lambda)  g(x) 
   + \tfrac{\gamma \bigl(\rho\|A\|_{\mathrm{op}}^2\bigr)}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \|x - \overline{x}\|^2.
\end{align*}
Hence $g$ is $(\rho\|A\|_{\mathrm{op}}^2, \gamma)$-weak quasar-convex at $\overline{x}$.

\label{theo:quasar-sepa}
Let $h_{i}: \mathbb{R}^{n_{i}} \rightarrow \mathbb{R}$, with $i \in \{1, \cdots, m\}$ be functions, with $n_{i} \geq 0$ and $\sum^{m}_{i=1} n_{i}=n$, and $h:\mathbb{R}^{n} \rightarrow \mathbb{R}$ be a function such that
\begin{equation}\label{eq:quasar-separable}
 h(x_{1}, \cdots, x_{m})=\sum_{i=1}^{m} h_{i}(x_{i}),
\end{equation}
Let $\overline{x} = (\overline{x}_{1}, \cdots ,\overline{x}_{m}) \in \mathbb{R}^{n}$. Then, for any $\rho \geq 0$ and $\gamma \in ]0,1]$, $h$ is $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^{n}}~h$ if and only if every $h_i$ is $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x}_{i} \in \operatorname{argmin}_{ \mathbb{R}^{n_{i}}} h_{i}$ (with the \emph{same} $\rho$ and $\gamma$).

\label{theo:char}
 Assume $h$ is a locally Lipschitz function with a convex domain. Then $h$ is $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin} h$, where $\rho \geq 0$ and $\gamma \in   ]0, 1]$, if and only if for every $x \neq \overline{x}$, we have
\begin{equation}\label{Clarke:char}
 h(\overline{x}) \geq h(x) + \tfrac{1}{\gamma} \langle v, \overline{x} - x \rangle - \tfrac{\rho}{2} \|x - \overline{x}\|^2, ~ \forall  v \in \partial^{C} h(x).
\end{equation}

\label{cor:star-first_order}
 Assume that $h$ is continuously differentiable on a convex domain $\operatorname{dom}(h)$. Then $h$ is $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin} h$, where $\rho \geq 0$ and $\gamma \in   ]0, 1]$, if and only if 
\begin{equation*}
 h(\overline{x})  \geq h(x) + \tfrac{1}{\gamma} \langle \nabla h(x), \overline{x} - x \rangle - \tfrac{\rho}{2} \|x - \overline{x}\|^2.
\end{equation*}

Let $x \in \mathcal{L}_{\zeta}^h (\mathbb{R}^n, \overline{x})$. By the first-order characterization in Corollary~\ref{cor:star-first_order}, we have (the fundamental gradient bound)
\begin{equation}\label{eq:grad_ineq_wqc}
    \langle \nabla h(x), x - \overline{x} \rangle \geq \gamma(h(x) - h(\overline{x})) - \tfrac{\gamma\rho}{2} \|x - \overline{x}\|^2.
\end{equation}

Since $x \in \mathcal{L}_{\zeta}^h (\mathbb{R}^n,\overline{x})$, the local quadratic growth condition \eqref{eq:QG} applies, giving $h(x) - h(\overline{x}) \geq \tfrac{\mu}{2}\|x - \overline{x}\|^2$. Because $\gamma > 0$, we can substitute this lower bound into \eqref{eq:grad_ineq_wqc} to obtain

\begin{equation*}
    \langle \nabla h(x), x - \overline{x} \rangle \geq \gamma\left(\tfrac{\mu}{2}\|x - \overline{x}\|^2\right) - \tfrac{\gamma\rho}{2} \|x - \overline{x}\|^2 = \tfrac{\gamma(\mu - \rho)}{2} \|x - \overline{x}\|^2.
\end{equation*}

Now, suppose for the contrary that there exists a spurious stationary point $x \in \mathcal{L}_{\zeta}^h (\mathbb{R}^n,\overline{x})$ with $x \neq \overline{x}$. Hence, $\nabla h(x) = 0$. Also, since $\gamma > 0$ and $\mu > \rho$ by assumption, we get $\gamma(\mu - \rho) > 0$, and since $x \neq \overline{x}$, $\|x - \overline{x}\|^2 > 0$.  Consequently,
\begin{equation*}
    0 \geq \tfrac{\gamma(\mu - \rho)}{2} \|x - \overline{x}\|^2 > 0,
\end{equation*}
a contradiction. Therefore, no such spurious stationary point can exist in $\mathcal{L}_{\zeta}^h (\mathbb{R}^n,\overline{x})$.

\label{rem:alternative_sufficient_QG}
 Several other well-known regularity conditions guarantee the local quadratic growth condition \eqref{eq:QG}. Notably, \emph{local strong (quasar-)convexity} inherently enforces a quadratic lower bound, directly satisfying the QG condition. Furthermore, the \emph {Restricted Secant Inequality (RSI)} ensures that the gradient points sufficiently toward the optimal set; as established in the literature, strong quasar-convexity and strong star quasi-convexity imply the RSI, which is fundamentally linked to and often used to derive quadratic growth \cite[Properties 6.13, 6.14, 6.17, 6.18]{khademi2026convexity}. These conditions collectively form a hierarchy of regularity that relaxes classical strong convexity while preserving the favorable algorithmic guarantees provided by local QG.
 \qed

\label{prop:LQG_WQC_implies_RSI}
 Let $h: \mathbb{R}^n \to \mathbb{R}$ be a continuously differentiable and $(\rho,\gamma)$-weakly quasar-convex function with respect to $\overline{x} \in \operatorname{argmin} h$, with $\rho\geq 0$ and $\gamma \in ]0,1]$. If $h$ satisfies the $\mu$-local quadratic growth condition \eqref{eq:QG} on $\mathcal{L}_{\zeta}^h(\mathbb{R}^n, \overline{x})$ for some $\zeta > 0$ and $\mu > \rho$, then $h$ satisfies RSI on $\mathcal{L}_{\zeta}^h(\mathbb{R}^n, \overline{x})$ with parameter $\nu = \tfrac{\gamma (\mu - \rho)}{2} > 0$, that is,
\begin{equation}\label{eq:RSI_derived}
 \langle \nabla h(x), x - \overline{x} \rangle \geq \tfrac{\gamma (\mu - \rho)}{2} \|x - \overline{x} \|^2, ~ \forall  x \in \mathcal{L}_{\zeta}^h (\mathbb{R}^n, \overline{x}).
\end{equation}

By the first-order characterization of $(\rho, \gamma)$-weakly quasar-convexity (Corollary \ref{cor:star-first_order}), we have 
\begin{equation*}
 \langle \nabla h(x), x - \overline{x} \rangle \geq \gamma \bigl( h(x) - h(\overline{x}) \bigr) - \tfrac{\gamma \rho}{2} \|x - \overline{x}\|^2, ~ \forall  x \in \mathbb{R}^{n}.
\end{equation*}
Since the local quadratic growth condition \eqref{eq:QG} holds, there exists $\zeta > 0$ such that for all $x \in \mathcal{L}_{\zeta}^h(\mathbb{R}^n, \overline{x})$ we have $h(x) - h(\overline{x}) \geq \tfrac{\mu}{2}\|x - \overline{x}\|^2$. Using this in the previous inequality and since $\gamma > 0$, we obtain
\begin{equation*}
    \langle \nabla h(x), x - \overline{x} \rangle \geq \gamma\left(\tfrac{\mu}{2}\|x - \overline{x}\|^2\right) - \tfrac{\gamma\rho}{2} \|x - \overline{x}\|^2 = \tfrac{\gamma(\mu - \rho)}{2} \|x - \overline{x}\|^2,
\end{equation*}
which completes the proof.

\label{prop:moreau-structural}
Let $h: \mathbb{R}^n \to \overline{\mathbb{R}}$ be proper, lower semicontinuous, and $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$, with $\rho\geq 0$ and $\gamma \in ]0,1]$. Let 
\begin{equation}\label{param:cond:2}
 0 < \beta < \tfrac{2-\gamma}{\rho\gamma},
\end{equation} 
with the convention that the right-hand side is $+\infty$ when $\rho = 0$. Then $h^{\beta}$ is $(\rho_{\beta}, \gamma)$-weakly quasar-convex with respect to the same point $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h^{\beta}$, where
\begin{equation}\label{eq:rho-mu}
 \rho_{\beta} = \frac{(2-\gamma)\rho}{(2-\gamma) - \gamma \rho {\beta}} \ge 0 .
\end{equation}

\label{coercivity:2}
Let $h:\mathbb{R}^n\to\overline{\mathbb{R}}$ be proper with $\overline{x}\in\operatorname{argmin}_{\mathbb{R}^n}h$, and let $\beta>0$.
Then, for every $x\in\mathbb{R}^n$, the function
$\Phi(y):=h(y)+\tfrac{1}{2\beta}\|x-y\|^2$ is $2$-supercoercive; more precisely,
\begin{equation}\label{eq:2-supercoercive}
  \Phi(y)\ \ge\ h(\overline{x})+\tfrac{1}{2\beta}\|x-y\|^2\quad\forall y\in\mathbb{R}^n,
  \qquad\text{hence}\qquad
  \liminf_{\|y\|\to\infty}\frac{\Phi(y)}{\|y\|^2}\ \ge\ \frac{1}{2\beta}>0 .
\end{equation}

\label{prop:quasar-prox-char}
Let $\mathcal{K} \subseteq \mathbb{R}^{n}$ be a closed convex set and $h: \mathbb{R}^n \to \overline{\mathbb{R}}$ be a proper, lower semicontinuous and $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathcal{K}} h$ ($\gamma \in   ]0, 1]$ and $\rho \geq 0$) on $\mathcal{K} \subseteq \operatorname{dom}(h)$. 
Let $z \in \mathcal{K}$ and $\beta > 0$. If $x^* \in \operatorname{Prox}_{\beta h} (\mathcal{K}, z)$, then
\begin{equation}\label{eq:quasar-prox-char}
 h(x^*) - h(\overline{x}) \leq \tfrac{1}{\gamma\beta} \langle x^* - z, \overline{x} - x^* \rangle + \tfrac{\rho}{2} \| x^* - \overline{x} \|^{2}.
\end{equation}

Since $x^* \in \operatorname{Prox}_{\beta h} (\mathcal{K}, z)$, we have
\begin{equation}\label{eq:prox-ineq}
 h(x^*) + \tfrac{1}{2\beta} \| x^* - z \|^{2} \leq h(x) + \tfrac{1}{2\beta} \| x - z \|^{2}, ~ \forall  x \in \mathcal{K}.
\end{equation}

Fix $\lambda \in ]0, 1]$ and set $x = \lambda \overline{x} + (1-\lambda)x^* \in \mathcal{K}$. Since $h$ is  $(\rho, \gamma)$-weakly quasar-convex,
{\small\begin{align*}
 h(x^*) + \tfrac{1}{2\beta} \| x^* - z \|^{2} & \leq \gamma\lambda  h(\overline{x}) + (1 - \gamma\lambda)  h(x^*) + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \| x^* - \overline{x} \|^{2} + \tfrac{1}{2 \beta} \| \lambda \overline{x} + (1-\lambda)x^* - z \|^{2} \\
 & = \gamma\lambda  h(\overline{x}) + (1 - \gamma\lambda)  h(x^*) + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \| x^* - \overline{x} \|^{2} \\
&\quad + \tfrac{\lambda}{2\beta} \| \overline{x} - z \|^{2} 
   + \tfrac{1-\lambda}{2\beta} \| x^* - z \|^{2} 
   - \tfrac{\lambda(1-\lambda)}{2\beta} \| \overline{x} - x^* \|^{2}.
\end{align*}}
That is,
\begin{align*}
\gamma\lambda \bigl( h(x^*) - h(\overline{x}) \bigr) &\leq \tfrac{\lambda}{2\beta} \bigl( \| \overline{x} - z \|^{2} - \| x^* - z \|^{2} \bigr)  + \tfrac{\gamma\rho}{2}  \lambda\left(1 - \tfrac{\lambda}{2-\gamma}\right) \| x^* - \overline{x} \|^{2} - \tfrac{\lambda(1-\lambda)}{2\beta} \| \overline{x} - x^* \|^{2}.
\end{align*}

Dividing by $\lambda > 0$ and using identity \eqref{id:3points}, we obtain
\begin{align*}
 \gamma \bigl( h(x^*) - h(\overline{x}) \bigr) 
 & \leq \tfrac{1}{\beta} \langle x^* - z, \overline{x} - x^* \rangle + \tfrac{1}{2\beta} \| \overline{x} - x^* \|^{2} + \tfrac{\gamma\rho}{2} \left(1 - \tfrac{\lambda}{2-\gamma}\right) \| x^* - \overline{x} \|^{2} - \tfrac{1-\lambda}{2\beta} \| \overline{x} - x^* \|^{2} \\
 & = \tfrac{1}{\beta} \langle x^* - z, \overline{x} - x^* \rangle + \tfrac{\lambda}{2\beta} \| x^* - \overline{x} \|^{2} + \tfrac{\gamma\rho}{2} \left(1 - \tfrac{\lambda}{2-\gamma}\right) \| x^* - \overline{x} \|^{2},
\end{align*}
and the result follows by taking $\lambda \downarrow 0$.

\label{prop:quasar-prox-descent}
 Let $\mathcal{K} \subseteq \mathbb{R}^{n}$ be a closed convex set and $h: \mathbb{R}^n \to \overline{\mathbb{R}}$ be a proper, lower semicontinuous, and $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathcal{K}} h$ ($\gamma \in   ]0, 1]$ and $\rho \geq 0$) on $\mathcal{K} \subseteq \operatorname{dom}(h)$. Then for every $z \in \mathcal{K}$, $\beta > 0$ and $x^* \in \operatorname{Prox}_{\beta h} (\mathcal{K}, z)$, we have
\begin{equation}\label{eq:quasar-prox-descent}
 h(x^*) + \tfrac{1}{2\beta} \| x^* - z \|^{2} \leq h(z).
\end{equation}
Furthermore, if $0 < \gamma\beta\rho < 1$, then
\begin{equation*}
\| x^* - \overline{x} \| \leq \frac{1}{\sqrt{1 - \gamma\beta\rho}}  \| z - \overline{x} \|.
\end{equation*}

The inequality \eqref{eq:quasar-prox-descent} holds for any proper functions (does not need convexity assumptions), and follows directly by taking $x = z$ in \eqref{eq:prox-ineq}.


For the second part, from relation \eqref{eq:quasar-prox-char} and since $h(x^*) \geq h(\overline{x})$, we have

$$0 \leq \tfrac{1}{\gamma\beta} \langle x^* - z, \overline{x} - x^* \rangle + \tfrac{\rho}{2} \| x^* - \overline{x} \|^{2}.$$

Using identity \eqref{id:3points} we obtain 
\begin{align*}
 & 0 \leq \tfrac{1}{2\gamma\beta} \left( \| \overline{x} - z \|^{2} - \| x^* - z \|^{2} - \| \overline{x} - x^* \|^{2} \right) + \tfrac{\rho}{2} \| x^* - \overline{x} \|^{2}, \\ 
  \Longrightarrow & \left( \tfrac{1}{\gamma\beta} - \rho \right) \| x^* - \overline{x} \|^{2} \leq \tfrac{1}{\gamma\beta} \left( \| \overline{x} - z \|^{2} - \| x^* - z \|^{2} \right).
\end{align*}

Since $\| x^* - z \|^{2} \geq 0$, the right-hand side is bounded above by $\tfrac{1}{\gamma\beta} \| \overline{x} - z \|^{2}$. Under the assumption $0 < \gamma\beta\rho < 1$ (so that $\tfrac{1}{\gamma\beta} - \rho > 0$), we obtain
\begin{equation*}
\| x^* - \overline{x} \|^{2} \leq \frac{\tfrac{1}{\gamma\beta}}{\tfrac{1}{\gamma\beta} - \rho}  \| \overline{x} - z \|^{2} = \tfrac{1}{1 - \gamma\beta\rho}  \| z - \overline{x} \|^{2},
\end{equation*}
which completes the proof.

\label{prop:ppm-descent}
 Let $h: \mathbb{R}^n \to \overline{\mathbb{R}}$ be proper, lower semicontinuous, and $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{ \mathbb{R}^n} h$, with $\rho \geq 0$ and $\gamma \in   ]0, 1]$. Then for every $\beta_k > 0$ and $x^{k+1} \in {\rm Prox}_{\beta_k h} (x^k)$, we have
\begin{equation}\label{eq:descent}
 h(x^{k+1}) + \tfrac{1}{2\beta_k}\|x^{k+1} - x^k\|^2 \leq h(x^k).
\end{equation}
In particular, $\{h(x^k)\}_{k}$ is a non-increasing sequence.

\label{Prop: 1}
Let $\mathcal{K} \subset \mathbb{R}^n$ be a closed convex set and $h: \mathbb{R}^n \rightarrow \overline{ \mathbb{R}}$ be a proper, lower semicontinuous and $(\rho, \gamma)$-weakly quasar-convex function with respect to $\overline{x} \in \operatorname{argmin}_{\mathcal{K}} h$ ($\gamma \in   ]0,1]$ and $\rho \geq 0$) on $\mathcal{K} \subset \operatorname{dom}(h)$, $x^k \in \mathbb{R}^n$ and $\beta_{k} > 0$ for all $k \in \mathbb{N}_{0}$. If $x^{k+1} \in {\rm Prox}_{\beta_{k} h}(\mathcal{K}, x^k)$, then
\begin{equation}\label{eq:prop1}
 h\left(x^{k+1}\right) - h(\overline{x}) \leq \tfrac{\rho}{2} \left\|x^{k+1} - \overline{x} \right\|^2 + \tfrac{1}{\gamma \beta_{k}} \langle x^{k+1} - x^k, \overline{x} -x^{k+1} \rangle.
\end{equation}

\label{thm:ppm-linear}
 Let $h:\mathbb{R}^n\to\overline{\mathbb{R}}$ be proper, lower semicontinuous, $(\rho,\gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{ \mathbb{R}^n}h$, with $\rho \geq 0$ and $\gamma \in   ]0, 1]$, and that satisfies the $\mu$-local quadratic growth condition \eqref{eq:QG}. Assume that $\mu>\rho$. Let $\{x^k\}_{k}$ be generated by Algorithm \ref{Alg: PPM} with step sizes $\{\beta_{k}\}_{k}$ satisfying \eqref{param:cond-2}. If $x^0 \in \mathcal{L}_{\zeta}^h (\mathbb{R}^n, \overline{x})$ for some $\zeta>0$, then setting
\begin{equation}\label{eq:tau}
 \tau := \frac{1}{1+ (\mu-\rho)\gamma \beta^{\prime}} \in   ]0, 1[,
\end{equation}
we have for every $k \in \mathbb{N}_{0}$ that:
\begin{itemize}
 \item[$(a)$] $x^k\in\mathcal{L}_{\zeta}^h(\mathbb{R}^n,\overline{x})$.

 \item[$(b)$] $\|x^{k+1}-\overline{x}\|^2 \leq \tau   \|x^k-\overline{x}\|^2 \leq \tau^{ k+1}\|x^0-\overline{x}\|^2$.

 \item[$(c)$] $h(x^k)\to h(\overline{x})$.
\end{itemize}

$(a)$: It follows by Lemma~\ref{prop:ppm-descent} that
\begin{equation}\label{eq:descent-use}
 h(x^{k+1}) \leq h(x^{k+1}) + \tfrac{1}{2\beta_k} \|x^{k+1}-x^k\|^2 \leq h(x^k).
\end{equation}
Hence $\{h(x^k)\}$ is non-increasing, and by induction $h(x^k)\leq h(x^0) \leq h(\overline{x})+\zeta$, so $x^k\in\mathcal{L}_{\zeta}^h(\mathbb{R}^n, \overline{x})$ for every $k \in \mathbb{N}_{0}$.

\noindent
$(b)$: Applying Proposition~\ref{Prop: 1} with $\mathcal{K}=\mathbb{R}^n$ and rearranging yields
\begin{equation}\label{eq:key}
 2 \langle x^{k+1}-x^k,  x^{k+1}-\overline{x} \rangle \leq \rho\gamma\beta_k \|x^{k+1}-\overline{x} \|^2 + 2 \gamma\beta_k (h(\overline{x}) - h(x^{k+1})).
\end{equation}

Since $x^{k+1}\in\mathcal{L}_{\zeta}$ by part $(a)$, condition~\eqref{eq:QG} gives
\begin{equation}\label{eq:QG-applied}
 h(x^{k+1})-h(\overline{x}) \geq \tfrac{\mu}{2} \|x^{k+1}-\overline{x}\|^2,
\end{equation}
so that $h(\overline{x}) - h(x^{k+1}) \leq - \frac{\mu}{2} \|x^{k+1} - \overline{x}\|^2$. Substituting into~\eqref{eq:key},
\begin{equation}\label{eq:key2}
 2 \langle x^{k+1}-x^k,  x^{k+1} - \overline{x} \rangle \leq - (\mu-\rho) \gamma \beta_k \|x^{k+1}-\overline{x}\|^2.
\end{equation}

Using \eqref{id:3points}, we have
\begin{align}
 & \|x^{k+1}-\overline{x}\|^2 - \|x^k-\overline{x}\|^2 + \|x^{k+1}-x^k\|^2 \leq - (\mu-\rho) \gamma \beta_k \|x^{k+1}-\overline{x}\|^2, \notag \\
 & \hspace{1.05cm} \Longrightarrow \bigl( 1 + (\mu-\rho) \gamma \beta_k \bigr) \|x^{k+1} - \overline{x}\|^2 \leq \|x^k - \overline{x}\|^2. \label{eq:contraction}
\end{align}

Since $\mu>\rho$, $\gamma>0$, and $\beta_k \geq \beta^{\prime}>0$, we have $1+(\mu-\rho) \gamma \beta_k \geq 1+(\mu-\rho) \gamma \beta^{\prime} = \tfrac{1}{\tau} >1$, where $\tau \in ]0, 1[$ is defined in~\eqref{eq:tau}. Dividing \eqref{eq:contraction} by $1+(\mu-\rho)\gamma\beta_k$ yields
\begin{equation*}
 \|x^{k+1}-\overline{x}\|^2 \leq \tfrac{1}{1+(\mu-\rho) \gamma \beta_k} \|x^k - \overline{x}\|^2 \leq \tau  \|x^k - \overline{x}\|^2.
\end{equation*}
Applying this bound recursively, we obtain $(b)$.


\noindent
$(c)$: Since $\overline{x}$ is a global minimizer of $h$, $h(x^{k+1}) \geq h(\overline{x})$ for all $k$. Furthermore, by applying Proposition~\ref{Prop: 1} with $\mathcal{K}=\mathbb{R}^n$, we get
\begin{equation}\label{eq:upper-raw}
 0 \leq h(x^{k+1}) - h(\overline{x}) \leq \tfrac{\rho}{2}\|x^{k+1}-\overline{x}\|^2 + \tfrac{1}{\gamma\beta_k} \langle x^{k+1} - x^k, \overline{x} - x^{k+1}\rangle.
\end{equation}
Applying the Cauchy-Schwarz inequality to the inner product and using $\beta_k\geq\beta^{\prime}>0$, we get
\begin{equation}\label{eq:upper}
 h(x^{k+1}) - h(\overline{x}) \leq \tfrac{\rho}{2} \|x^{k+1}-\overline{x}\|^2 + \tfrac{1}{\gamma \beta^{\prime}} \|x^{k+1}-x^k\| \cdot \|x^{k+1}-\overline{x}\|.
\end{equation}
From part $(b)$, we know that $\|x^{k}-\overline{x}\|\leq\tau^{k/2}\|x^0-\overline{x}\|\to 0$. By the triangle inequality,
\begin{equation*}
 \|x^{k+1}-x^k\| \leq \|x^{k+1}-\overline{x}\| + \|x^k-\overline{x}\| \leq \bigl( \tau^{(k+1)/2} + \tau^{k/2}\bigr) \|x^0-\overline{x}\| \to 0.
\end{equation*}
Hence both $\|x^{k+1}-\overline{x}\|\to 0$ and $\|x^{k+1}-x^k\|\to 0$, so the
right-hand side of~\eqref{eq:upper} tends to $0$. Combining with \eqref{eq:upper-raw} yields $h(x^k)\to h(\overline{x})$, which completes the proof.

\label{cor:ppm-rates}
Under the same assumptions as Theorem~\ref{thm:ppm-linear}, the following hold:
\begin{itemize}
 \item[$(a)$] The sequence of iterates $\{x^k\}_{k}$ converges $Q$-linearly to $\overline{x}$ with Q-factor $\sqrt{\tau}$, i.e.,
 \begin{equation}
  \|x^{k+1} - \overline{x}\| \leq \frac{1}{\sqrt{1+ (\mu-\rho)\gamma \beta^{\prime}}} \|x^k - \overline{x}\|, ~ \forall  k \in \mathbb{N}_0.
 \end{equation}
 \item[$(b)$] The sequence of function values $\{h(x^k)\}_{k}$ converges R-linearly to $h(\overline{x})$ with R-factor $\sqrt{\tau}$, i.e.,
 \begin{equation}
  h(x^k) - h(\overline{x}) \leq C  (\sqrt{\tau})^{k-1}, ~ \forall k \in \mathbb{N},
 \end{equation}
 where
 \begin{equation}\label{eq:C-def}
  C := \left(\tfrac{\rho}{2} + \tfrac{1}{\gamma\beta'}\big(1+\sqrt{\tau}\big)\right)\|x^0-\overline{x}\|^2.
 \end{equation}
\end{itemize}

$(a)$: This follows directly from Theorem \ref{thm:ppm-linear}$(b)$. The contraction factor $\tau$ comes from the inequality
\begin{equation*}
 \|x^{k+1} - \overline{x}\|^2 \leq \tfrac{1}{1 + (\mu - \rho) \gamma\beta_k}\|x^k - \overline{x}\|^2 \leq \tau \|x^k - \overline{x}\|^2,
\end{equation*}
where the last inequality uses $\beta_k \ge \beta'$ from \eqref{param:cond-2}, and the result follows by applying this recursively.

$(b)$: From Proposition~\ref{prop:quasar-prox-char} with $\mathcal{K}=\mathbb{R}^n$, we have
\begin{equation*}                          
 h(x^{k+1}) - h(\overline{x}) \leq \tfrac{\rho}{2} \|x^{k+1} - \overline{x}\|^2 + \tfrac{1}{\gamma \beta_k} \langle x^{k+1} - x^k, \overline{x} - x^{k+1}\rangle.
\end{equation*}
Applying the Cauchy-Schwarz inequality and using $\beta_k \ge \beta' > 0$, we get
\begin{equation*}
 h(x^{k+1}) - h(\overline{x}) \leq \tfrac{\rho}{2} \|x^{k+1}-\overline{x}\|^2 + \tfrac{1}{\gamma \beta'} \|x^{k+1}-x^k\| \cdot \|x^{k+1}-\overline{x}\|.
\end{equation*}
Using part $(a)$ and the triangle inequality,
\begin{equation*}
 \|x^{k+1} - x^k\| \leq \|x^{k+1} - \overline{x}\| + \|x^k - \overline{x}\| \leq \left(\tau^{(k+1)/2} + \tau^{k/2} \right)\|x^0 - \overline{x}\|.
\end{equation*}
Substituting and simplifying,
\begin{align*}
 h(x^{k+1}) - h(\overline{x}) & \leq \left( \tfrac{ \rho}{2} \tau^{k+1} + \tfrac{1}{\gamma \beta'} ( \tau^{(k+1)/2} + \tau^{k/2}) \tau^{ (k+1)/2} \right) \|x^0 - \overline{x}\|^2 \\
 & \leq \left( \tfrac{\rho}{2} + \tfrac{1}{\gamma \beta'} (1 + \sqrt{\tau}) \right) \tau^{k/2} \|x^0 - \overline{x}\|^2 \\
 & = C  \tau^{k/2},
\end{align*}
with $C$ as in \eqref{eq:C-def}. Since this bounds $h(x^{k+1})-h(\overline x)$ for every $k\in \mathbb{N}_0$, reindexing $n:=k+1$ gives
\begin{equation*}
 h(x^n) - h(\overline{x}) \leq C  \tau^{(n-1)/2} = C (\sqrt\tau)^{n-1}, ~ \forall  n \geq 1,
\end{equation*}
which is the claimed bound.

\label{cor:ppm-complexity}
Under the same assumptions as Corollary~\ref{cor:ppm-rates}, the following assertions hold:
\begin{itemize}
\item[$(a)$] For any $\varepsilon > 0$, after at most
\begin{equation}\label{eq:complexity-iter}
 K_{\mathrm{iter}}(\varepsilon) = \left\lceil \tfrac{2}{- \ln (\tau)} \ln\left(\tfrac{\|x^0 - \overline{x}\|}{\varepsilon} \right) \right\rceil
\end{equation}
iterations, we have $\|x^K - \overline{x}\| \leq \varepsilon$.

\item[$(b)$] For any $\varepsilon > 0$, after at most
\begin{equation}\label{eq:complexity-func}
 K_{\mathrm{func}}(\varepsilon) = \left\lceil 1+ \tfrac{2}{-\ln (\tau)} \ln\left( \tfrac{C}{\varepsilon} \right) \right\rceil
\end{equation}
iterations, we have $h(x^K) - h(\overline{x}) \leq \varepsilon$, where $C$ is defined in Corollary \ref{cor:ppm-rates}.
\end{itemize}
In both cases, the iteration complexity is $O \left(\tfrac{1}{-\ln (\tau)} \ln(1/\varepsilon) \right)$, which is the standard complexity for linearly convergent methods.

\label{def:prox-residual}
 Let $h:\mathbb{R}^n\to\overline{\mathbb{R}}$ be proper, lower semicontinuous, and $\beta>0$. For $x \in \mathbb{R}^n$ and $x^{*} \in \operatorname{Prox}_{\beta h}(x)$, the proximal residual at $x$ (associated with $x^*$) is defined by
\begin{equation*}
 r_{\beta}(x) := \tfrac{1}{\beta}\left(x - x^{*} \right).
\end{equation*}

\label{prop:prox-PL}
 Let $h: \mathbb{R}^n \to \overline{\mathbb{R}}$ be proper, lower semicontinuous, $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} h$, and satisfy the $\mu$-quadratic growth condition \eqref{eq:QG} at $\overline{x}$ globally on $\mathbb{R}^n$ (i.e., for every $\zeta>0$), with $\mu > \rho$. Let $\beta > 0$, $x \in \mathbb{R}^n$, and $x^{*} \in \operatorname{Prox}_{\beta h} (x)$. Then,
\begin{equation}\label{eq:prox-PL}
 h(x^{*}) - h(\overline{x})   \leq   \tfrac{2\mu}{\gamma^{2}(\mu-\rho)^{2}} \|r_{\beta}(x)\|^{2}.
\end{equation}

Taking $z=x$ in Proposition \ref{prop:quasar-prox-char}, we obtain
\begin{equation*}
 h(x^{*}) - h(\overline{x})   \leq   \tfrac{1}{\gamma\beta}\langle x^{*}-x, \overline{x}-x^{*}\rangle + \tfrac{\rho}{2} \|x^{*}-\overline{x}\|^{2}.
\end{equation*}
By definition, $x^{*}-x = -\beta  r_{\beta}(x)$, so, applying the Cauchy-Schwarz inequality,
\begin{equation*}
 \tfrac{1}{\gamma\beta}\langle x^{*}-x, \overline{x}-x^{*}\rangle = -\tfrac{1}{\gamma} \langle r_{\beta}(x), \overline{x}-x^{*} \rangle   \leq   \tfrac{1}{\gamma} \|r_{\beta}(x)\| \|x^{*}-\overline{x}\|.
\end{equation*}
Combining the two displays,
\begin{equation}\label{eq:prox-PL-step1}
 h(x^{*}) - h(\overline{x})   \leq   \tfrac{1}{\gamma} \|r_{\beta}(x)\| \|x^{*}-\overline{x}\| + \tfrac{\rho}{2} \|x^{*}-\overline{x}\|^{2}.
\end{equation}
On the other hand, by the $\mu$-local quadratic growth condition \eqref{eq:QG} applied at $x^{*}$, we have $h(x^{*}) - h(\overline{x})   \geq   \tfrac{\mu}{2}\|x^{*}-\overline{x}\|^{2}$. Combining this lower bound with \eqref{eq:prox-PL-step1} gives
\begin{equation*}
 \tfrac{\mu}{2} \|x^{*}- \overline{x}\|^{2}   \leq   \tfrac{1}{\gamma} \|r_{\beta}(x)\| \|x^{*}-\overline{x}\| + \tfrac{\rho}{2} \|x^{*}-\overline{x} \|^{2}.
\end{equation*}

If $x^{*}= \overline{x}$, then \eqref{eq:prox-PL} holds trivially since $h(x^*) - h(\overline x) = 0$. Otherwise, dividing by $\|x^{*}- \overline{x}\| >0$ and rearranging, using $\mu > \rho$, we get $\|x^{*} - \overline{x}\|   \leq   \tfrac{2}{\gamma (\mu - \rho)} \|r_{\beta}(x)\|$. Substituting this bound back into \eqref{eq:prox-PL-step1},
\begin{align*}
 h(x^{*}) - h(\overline{x}) & \leq \tfrac{1}{\gamma} \|r_{\beta}(x)\| \tfrac{2}{ \gamma (\mu-\rho)} \|r_{\beta}(x)\| + \tfrac{\rho}{2} \left(\tfrac{2}{\gamma (\mu-\rho)} \right)^{2} \|r_{\beta}(x)\|^{2} \\
 & = \tfrac{2}{\gamma^{2} (\mu-\rho)} \|r_{\beta}(x) \|^{2} + \tfrac{2 \rho}{\gamma^{2} (\mu-\rho)^{2}} \|r_{\beta}(x) \|^{2} \\

 & = \tfrac{2 \mu}{\gamma^{2} (\mu-\rho)^{2}} \| r_{\beta} (x)\|^{2},
\end{align*}
which is \eqref{eq:prox-PL}.

\label{cor:ppm-residual-rate}
 Under the same assumptions as Corollary \ref{cor:ppm-rates}, let $\{x^k\}_{k}$ be generated by Algorithm \ref{Alg: PPM} with $\beta_k \equiv \beta'$ satisfying \eqref{param:cond-2}, and set $$r^{k} := r_{\beta'}(x^{k}) = \tfrac{1}{\beta'} (x^k - x^{k+1}).$$ 
 Then,
\begin{equation}\label{eq:residual-rate}
 \|r^{k}\|   \leq   \tfrac{1+\sqrt{\tau}}{\beta'}  (\sqrt{\tau})^{k}   \|x^0-\overline{x}\|, \qquad \forall   k \in\mathbb{N}_0.
\end{equation}

By the triangle inequality and Corollary~\ref{cor:ppm-rates}$(a)$,
\begin{equation*}
 \|r^{k}\| = \tfrac{1}{\beta'}\|x^{k}-x^{k+1}\| \leq \tfrac{1}{\beta'} \Big(\|x^{k}-\overline{x}\| + \|x^{k+1} - \overline{x}\| \Big) \leq \tfrac{1}{\beta'} (\tau^{k/2} + \tau^{(k+1)/2}) \|x^{0}-\overline{x}\|,
\end{equation*}
which simplifies to \eqref{eq:residual-rate}.

\label{cor:ppm-residual-complexity}
 Under the same assumptions as Corollary \ref{cor:ppm-rates}, let $\{x^k\}_{k}$ be generated by Algorithm \ref{Alg: PPM} with $\beta_k \equiv \beta'$ satisfying \eqref{param:cond-2}. Then for any $\varepsilon > 0$, after at most
\begin{equation}\label{eq:complexity-residual}
 K_{\mathrm{res}}(\varepsilon) = \left\lceil \tfrac{2}{-\ln (\tau)}\ln\left(\tfrac{(1+\sqrt{\tau}) \|x^0-\overline{x}\|}{\beta'\varepsilon} \right) \right\rceil
\end{equation}
iterations, we have $\|r^{K}\| \leq \varepsilon$; this criterion is computable online, without knowledge of $\overline{x}$, from $\|x^K-x^{K+1}\|$ alone. Moreover, if the assumptions of Proposition~\ref{prop:prox-PL} hold, then $\|r^K\|\leq\varepsilon$ implies
\begin{equation*}
 h(x^{K+1}) - h(\overline{x})   \leq   \tfrac{2\mu}{\gamma^{2}(\mu-\rho)^{2}} \varepsilon^{2}.
\end{equation*}
In both cases, the iteration complexity is $O\left(\tfrac{1}{-\ln (\tau)}\ln(1/\varepsilon)\right)$, matching the order already established in Corollary~\ref{cor:ppm-complexity}.

\label{lem:quadratic-perturbation}
Let $\phi: \mathbb{R}^n \to \overline{\mathbb{R}}$ be $(\rho, \gamma)$-weakly quasar-convex with respect to $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} \phi$, and suppose $\phi$ satisfies the $\mu$-local Quadratic Growth (QG) condition at $\overline{x}$ with parameter $\zeta > 0$. Then, for any $L \geq 0$, the perturbed function $\psi(x) := \phi(x) + L\|x - \overline{x}\|^2$ is $(\rho_L, \gamma)$-weakly quasar-convex with respect to $\overline{x}$, and satisfies the $\mu_L$-local QG condition at $\overline{x}$ with the same parameter $\zeta$, where
\begin{equation*}
    \rho_L = \max\left\{0,   \rho - 2L\left(\frac{2}{\gamma} - 1\right)\right\} \quad \text{and} \quad \mu_L = \mu + 2L.
\end{equation*}

First, observe that since $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} \phi$ and $L \geq 0$, we have $\psi(x) = \phi(x) + L\|x - \overline{x}\|^2 \geq \phi(\overline{x}) = \psi(\overline{x})$ for all $x \in \mathbb{R}^n$. This ensures that $\overline{x} \in \operatorname{argmin}_{\mathbb{R}^n} \psi$, which is a strict requirement for the definition of weak quasar-convexity. We now prove the two properties separately. For any $x \in \mathcal{L}_{\zeta}^{\psi}(\mathbb{R}^n, \overline{x})$, we have 
$$ \phi(x) \leq \psi(x) \leq \psi(\overline{x}) + \zeta = \phi(\overline{x}) + \zeta, $$ 
which implies $x \in \mathcal{L}_{\zeta}^{\phi}(\mathbb{R}^n, \overline{x})$. Therefore, the $\mu$-QG condition for $\phi$ applies to $x$. By the definition of $\psi$, we obtain
\begin{align*}
 \psi(x) - \psi(\overline{x}) &= \big(\phi(x) + L\|x - \overline{x}\|^2\big) - \big(\phi(\overline{x}) + 0\big) = \big(\phi(x) - \phi(\overline{x})\big) + L\|x - \overline{x}\|^2 \\
 & \geq \frac{\mu}{2}\|x - \overline{x}\|^2 + L\|x - \overline{x}\|^2 = \frac{\mu + 2L}{2}\|x - \overline{x}\|^2.
\end{align*}
Thus, $\psi$ satisfies the $\mu_L$-QG condition with $\mu_L = \mu + 2L$ on $\mathcal{L}_{\zeta}^{\psi}(\mathbb{R}^n, \overline{x})$.

Now, let $x_\lambda = \lambda \overline{x} + (1-\lambda)x$ for $\lambda \in [0,1]$. Note that $x_\lambda - \overline{x} = (1-\lambda)(x - \overline{x})$, which implies $\|x_\lambda - \overline{x}\|^2 = (1-\lambda)^2\|x - \overline{x}\|^2$. 

Using the definition of $\psi$ and the $(\rho, \gamma)$-weak quasar-convexity of $\phi$, we obtain
\begin{align*}
    \psi(x_\lambda) &= \phi(x_\lambda) + L\|x_\lambda - \overline{x}\|^2 \\
    &\leq \gamma \lambda \phi(\overline{x}) + (1-\gamma \lambda) \phi(x) + \frac{\gamma \rho}{2} \lambda \left(1 - \frac{\lambda}{2-\gamma}\right)\|x - \overline{x}\|^2 + L(1-\lambda)^2\|x - \overline{x}\|^2.
\end{align*}
Substitute $\phi(\overline{x}) = \psi(\overline{x})$ and $\phi(x) = \psi(x) - L\|x - \overline{x}\|^2$ into the inequality
\begin{align*}
    \psi(x_\lambda) &\leq \gamma \lambda \psi(\overline{x}) + (1-\gamma \lambda) \big(\psi(x) - L\|x - \overline{x}\|^2\big)  + \left[ \frac{\gamma \rho}{2} \lambda \left(1 - \frac{\lambda}{2-\gamma}\right) + L(1-\lambda)^2 \right] \|x - \overline{x}\|^2 \\
    &= \gamma \lambda \psi(\overline{x}) + (1-\gamma \lambda) \psi(x) + B(\lambda)\|x - \overline{x}\|^2,
\end{align*}
where $B(\lambda)$ is the coefficient of $\|x - \overline{x}\|^2$. We simplify $B(\lambda)$ by expanding the terms involving $L$
\begin{align*}
    B(\lambda) &= \frac{\gamma \rho}{2} \lambda \left(1 - \frac{\lambda}{2-\gamma}\right) + L \big( 1 - 2\lambda + \lambda^2 - 1 + \gamma \lambda \big) \\

    &= \frac{\gamma \rho}{2} \lambda \left(1 - \frac{\lambda}{2-\gamma}\right) - L \lambda (2-\gamma) \left( 1 - \frac{\lambda}{2-\gamma} \right) \\

    &= \frac{\gamma}{2} \left[ \rho - 2L\left(\frac{2}{\gamma} - 1\right) \right] \lambda \left( 1 - \frac{\lambda}{2-\gamma} \right).
\end{align*}
For $\lambda \in [0,1]$ and $\gamma \in ]0,1]$, the term $\lambda \left( 1 - \frac{\lambda}{2-\gamma} \right)$ is non-negative because $1 - \frac{\lambda}{2-\gamma} \geq 1 - \frac{1}{2-\gamma} = \frac{1-\gamma}{2-\gamma} \geq 0$. 
Therefore, to satisfy the definition of $(\rho_L, \gamma)$-weak quasar-convexity, we require
\begin{equation*}
    B(\lambda) \leq \frac{\gamma \rho_L}{2} \lambda \left( 1 - \frac{\lambda}{2-\gamma} \right).
\end{equation*}
This holds if and only if $\rho_L \geq \rho - 2L\left(\frac{2}{\gamma} - 1\right)$. Since the weak quasar-convexity modulus must be non-negative by definition, we take $\rho_L = \max\left\{0,   \rho - 2L\left(\frac{2}{\gamma} - 1\right)\right\}$, which completes the proof.

\label{exam:qg-radial} 
Let $\varphi:\mathbb{R}\to\mathbb{R}$ be the even function defined, for $t\geq0$, by
\begin{equation}\label{eq:phi-def}
\varphi(t) := \begin{cases}
 t^2, & 0\leq t\leq 1, \\[2mm]
 1+2(t-1)-\dfrac18(t-1)^2, & 1\leq t\leq 13, \\[2mm]
 7-(t-13)+(t-13)^2, & t\geq 13,
\end{cases}
\qquad \varphi(-t):=\varphi(t).
\end{equation}
Clearly, $\varphi$ is continuously differentiable on $\mathbb{R}$. Indeed, at $t=1$, both pieces give value $1$ and slope $2$, while at $t=13$, both pieces give value $7$ and slope $-1$, and $\varphi$ is smooth and even at $t=0$. We now record the main properties of $\varphi$.
\begin{itemize}
\item[$(i)$] {\rm Unique global minimizer.} $\varphi (0) = 0$, and $\varphi(t)>0$ for every $t\neq0$: on $[0, 1]$, $\varphi(t)=t^2>0$ for $t>0$; on $[1, 13]$, $\varphi$ increases from $\varphi(1) = 1$ to a strict local maximum $\varphi (9) = 9$ (since $\varphi' (t) = 2-\tfrac14 (t-1)$ vanishes exactly at $t=9$), then decreases to $\varphi(13) = 7$; on $[13, +\infty[$, $\varphi$ decreases further to a local minimum $\varphi(13.5) = \tfrac{27}{4}$ (since $\varphi'(t) = -1+ 2(t-13)$ vanishes at $t=13.5$), then increases to $+\infty$. In particular $\varphi(t) \geq \tfrac{27}{4}>0$ for all $t\geq13$. Hence, $\{0\} = \operatorname{argmin}_{\mathbb{R}} \varphi$.

\item[$(ii)$] {\rm Global weak convexity.} On $]0, 1[$, $\varphi''(t) = 2$; on $]1, 13[$, $\varphi'' (t) = -\tfrac14$; on $]13, + \infty[$, $\varphi'' (t) = 2$, with the corresponding formulas on the negative half-line by evenness. Since $\varphi + \tfrac18 \lvert \cdot \rvert^2$ is continuously differentiable and piecewise quadratic with nonnegative second derivative on each quadratic piece, its derivative is nondecreasing. Hence it is convex. Thus $\varphi$ is $\tfrac14$-weakly convex on $\mathbb{R}$. In particular, it is $(\rho,1)$-weakly quasar-convex with respect to $0$ for every $\rho\geq\tfrac14$, by \eqref{eq:quasar-wconvex}.

\item[$(iii)$] {\rm Local quadratic growth.} Since $\varphi(t) = t^2$ exactly on $[-1, 1]$, and $\varphi(t) \geq 1$ for every $t$ with $\lvert t \rvert \geq 1$ (as $\varphi$ increases on $[1,9]$ from $1$, decreases on $[9,13]$ to $7$, and is bounded below by $\tfrac{27}{4} > 1$ on $[13, + \infty[$), the sublevel set $\{t \in \mathbb{R}:   \varphi(t) \leq \zeta\}$ is contained in $[-1, 1]$ for every $\zeta \in ]0, 1[$, and on that set $\varphi (t) = t^2$ exactly. Hence $\varphi$ satisfies the $\mu$-local quadratic growth condition \eqref{eq:QG} at $\overline x=0$ with $\mu=2$, for every $\zeta \in ]0, 1[$.

\item[$(iv)$] {\rm Failure of (star) quasi-convexity.} The point $t=9$ lies on the segment joining $0$ and $13.5$, and $\varphi(9) = 9 >   \frac{27}{4} = \max\{\varphi(0),\varphi(13.5)\}$, which directly violates quasi-convexity and, in particular, star quasi-convexity with respect to $0$.

\item[$(v)$] {\rm Failure of quasar-convexity, for every $\gamma\in ]0,1]$.} Taking $x=13.5$ and $\lambda=\tfrac13$ (so that $(1-\lambda)x=9$), $\gamma$-quasar-convexity with respect to $0$ would require $\varphi(9)\leq\left(1-\tfrac\gamma3 \right) \varphi(13.5)$. Since $\varphi(13.5)=\tfrac{27}{4}$ and $1-\tfrac\gamma3\leq1$ for every $\gamma\in ]0,1]$, we get $\left(1-\frac\gamma3\right) \varphi (13.5)  \leq  \frac{27}{4}  =  6.75  <  9  =  \varphi(9)$, a contradiction for every $\gamma\in ]0,1]$. Hence $\varphi$ is not $\gamma$-quasar-convex with respect to $0$, for any $\gamma\in ]0,1]$.
\qed
\end{itemize}
